// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.consolidationimport android.content.Contextimport androidx.work.Constraintsimport androidx.work.ExistingPeriodicWorkPolicyimport androidx.work.NetworkTypeimport androidx.work.PeriodicWorkRequestBuilderimport androidx.work.WorkManagerimport com.roshan.persona.di.AppInitializerimport com.roshan.persona.di.Priorityimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singletonimport java.util.Calendarimport java.util.concurrent.TimeUnit/** * NOUS — Dream Mode Scheduler (Module 3 v2 — audit P0). * * Schedules the [DreamModeWorker] to run nightly between 2-4 AM when the * device is charging + idle. * * ## Constraints * *  - `setRequiresCharging(true)` — only run when plugged in. *  - `setRequiresDeviceIdle(true)` — only run when device is idle. *  - `setRequiresBatteryNotLow(true)` — don't run on low battery. *  - Network not required (consolidation uses local LLM). * * ## Timing * * WorkManager's periodic interval is 15 minutes minimum. We use a 24-hour * interval + an initial delay computed to land at ~2 AM local time. WorkManager * will then run it nightly around that time (subject to constraints). * * Strategy §3.7: "runs when device charging + idle". */@Singletonclass DreamModeScheduler @Inject constructor() {    /**     * Schedule the nightly Dream Mode consolidation.     *     * Idempotent — uses [ExistingPeriodicWorkPolicy.KEEP] so calling this     * multiple times doesn't create duplicate workers.     */    fun scheduleNightly(context: Context) {        try {            val constraints = Constraints.Builder()                .setRequiresCharging(true)                .setRequiresDeviceIdle(true)                .setRequiresBatteryNotLow(true)                .setRequiredNetworkType(NetworkType.NOT_REQUIRED)                .build()            // Compute initial delay to next 2 AM local time.            val now = Calendar.getInstance()            val twoAm = Calendar.getInstance().apply {                set(Calendar.HOUR_OF_DAY, 2)                set(Calendar.MINUTE, 0)                set(Calendar.SECOND, 0)                set(Calendar.MILLISECOND, 0)                if (timeInMillis <= now.timeInMillis) {                    add(Calendar.DAY_OF_MONTH, 1)                }            }            val initialDelayMinutes = ((twoAm.timeInMillis - now.timeInMillis) / (60_000L)).coerceAtLeast(1)            val request = PeriodicWorkRequestBuilder<DreamModeWorker>(                24, TimeUnit.HOURS,            )                .setConstraints(constraints)                .setInitialDelay(initialDelayMinutes, TimeUnit.MINUTES)                .build()            WorkManager.getInstance(context).enqueueUniquePeriodicWork(                DreamModeWorker.UNIQUE_WORK_NAME,                ExistingPeriodicWorkPolicy.KEEP,                request,            )            Timber.tag(TAG).i("Dream Mode scheduled — first run in ~$initialDelayMinutes min, then every 24h (charging + idle).")        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "Failed to schedule DreamModeWorker")        }    }    private companion object {        private const val TAG = "DreamModeScheduler"    }}/** * NOUS — Dream Mode Initializer (Module 3 v2). * * App initializer that schedules the DreamModeWorker at app boot. * Registered via Hilt multibinding (same pattern as SecurityInitializer). */@Singletonclass DreamModeInitializer @Inject constructor(    private val scheduler: DreamModeScheduler,    private val consolidationEngine: ConsolidationEngine,) : AppInitializer {    override val priority: Priority = Priority.LAZY    override val isBlocking: Boolean = false    override fun initialize(context: Context) {        // Wire the bridge so DreamModeWorker can access the engine.        DreamModeBridge.consolidationEngine = consolidationEngine        // Schedule the nightly run.        scheduler.scheduleNightly(context)    }}